    const s = { ship: 50, target: 50, fire: false, coolAt: 0, queue: shuffle(rnd, [...pickN(deck.a.items, n2), ...pickN(deck.b.items, n2)]), live: [], shots: [], bursts: [], spawnAt: 0, t: 0, n: 0, score: 0, hits: 0 };
