      if (s.queue.length && s.t >= s.spawnAt && s.live.length < 3) { const text = s.queue.shift(); s.live.push({ id: s.n++, text, yes: deck.a.items.includes(text), x: 14 + rnd() * 72, y: -5 }); s.spawnAt = s.t + 70 - Math.min(30, gone * 1.5); }
