  useEffect(() => { if (done) return undefined; const t = setInterval(() => setTicks((n) => n + 1), 1000); return () => clearInterval(t); }, [done]);
  useEffect(() => { if (done && onScore) onScore(ticks, 'low'); }, [done]);
